      const hooks = recordingHooks(callOrder, ['beforeSession', 'beforeUserInput', 'beforeModelResponse']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder[0]).toBe('beforeSession');
    });

    it('routes a failure through onError and afterSession before provider interaction', async () => {
      const failure = new Error('setup failed');
      const callOrder: string[] = [];
      let providerCalled = false;
      const provider = createMockProvider('unused');
      const originalSendMessage = provider.sendMessage;
      provider.sendMessage = params => {
        providerCalled = true;
        return originalSendMessage(params);
      };
      const hooks: OrchestratorHooks = {
        beforeSession: async () => {
          throw failure;
        },
        onError: async (_session, error) => void callOrder.push(error === failure ? 'onError' : 'wrongError'),
        afterSession: async () => void callOrder.push('afterSession'),
      };

      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
      const caught = await orchestrator.processMessage(createSession('hello')).catch((error: unknown) => error);

      expect({caught, callOrder, providerCalled}).toEqual({
        caught: failure,
